const D = { density:.55, spread:1, angleTweak:0, speed:1, energy:.6, hue:45, scale:1, x:.5, y:.5, style:'botanical', act:'bloom', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width,height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:.6);
const jr = i => { const s=Math.sin((i+1)*78.233 + P.seed*39.425)*43758.5453; return s-Math.floor(s); };
let N = Math.floor(120 + P.density*520);
if (st==='schematic') N=Math.min(N,420);
const key = width+'x'+height+st+((P.seed|0)%1000)+Math.round(P.hue);

// cached full-bleed base
if (!S.base || S.baseKey!==key){
  const g=createGraphics(width,height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  if (st==='engraving') g.background(40,10,86);
  else if (st==='botanical') g.background((P.hue*0.1+35)%360,17,85);
  else if (st==='schematic') g.background(218,58,12);
  else g.background((P.hue*0.1+250)%360,55,7);
  if (st==='engraving'||st==='botanical'){
    for(let i=0;i<680;i++){ const gx=jr(i*2+1)*width, gy=jr(i*2+3)*height; g.fill(35,14,jr(i)>.5?70:96, 8); g.circle(gx,gy,1+jr(i*2)*2.2); }
  }
  S.base=g; S.baseKey=key;
}
image(S.base,0,0);

const GA = Math.PI*(3-Math.sqrt(5));
const ga = GA + (P.angleTweak*Math.PI/180) + Math.sin(K.t*0.02)*0.0009;
const cx = P.x*width, cy = P.y*height;
const c = u*0.019*P.scale*P.spread;
const rot = K.t*0.05*P.speed + jr(0)*6.2832;

// bloom / decay dramaturgy
let bloom;
if (P.act==='seasons') bloom=0.5+0.5*Math.sin(K.t*0.045*P.speed);
else if (P.act==='pulse') bloom=0.55+0.45*Math.sin((K.section||0)*1.3 + K.swell*0.6);
else bloom=Math.min(1, 0.12 + K.t*0.012*P.speed);
const grown = Math.max(8, Math.floor(N*(0.1+bloom*0.9)));

if (st==='schematic'){
  stroke(190,72,95,55); strokeWeight(1); noFill();
  const fibs=[8,13,21];
  for(let i=0;i<grown;i++){
    const a=i*ga+rot, rr=c*Math.sqrt(i), x=cx+Math.cos(a)*rr, y=cy+Math.sin(a)*rr;
    for(let f=0;f<fibs.length;f++){ const j=i+fibs[f]; if(j<grown){ const aj=j*ga+rot, rj=c*Math.sqrt(j); if(f===0) line(x,y, cx+Math.cos(aj)*rj, cy+Math.sin(aj)*rj); } }
  }
  noStroke(); fill(190,55,100,75+K.pulse*20);
  for(let i=0;i<grown;i+=2){ const a=i*ga+rot, rr=c*Math.sqrt(i); circle(cx+Math.cos(a)*rr, cy+Math.sin(a)*rr, 2.2); }
} else {
  noStroke();
  if (st==='iridescent') blendMode(ADD);
  for(let i=0;i<grown;i++){
    const a=i*ga+rot;
    const rr=c*Math.sqrt(i)*(1+(jr(i)-.5)*0.03);
    const x=cx+Math.cos(a)*rr, y=cy+Math.sin(a)*rr;
    const norm=i/N;
    const edge=grown-i, pop= edge<26? edge/26 : 1;
    const beat=K.pulse*0.25*(1-norm) + A.treble*0.3*jr(i);
    const sz=u*(0.007+0.021*norm)*(0.8+P.energy*0.5)*P.scale*(0.55+pop*0.55)*(1+beat);
    if (st==='engraving'){
      const h=(P.hue*0.2+30)%360;
      fill(h,18,14+norm*20,70); circle(x,y,sz*0.7);
      if(jr(i*3)>0.6){ stroke(h,20,12,50); strokeWeight(0.8); const ha=a+1.2; line(x,y,x+Math.cos(ha)*sz*1.1,y+Math.sin(ha)*sz*1.1); noStroke(); }
    } else if (st==='iridescent'){
      const h=(P.hue + norm*160 + a*9 + K.t*10)%360, s=70+Math.sin(i*0.7)*20, al=30+beat*30;
      fill((h+360)%360,s,80+norm*20,al); circle(x,y,sz*1.6);
      fill((h+30)%360,s*0.6,100,al*0.7); circle(x,y,sz*0.8);
    } else {
      const t=norm;
      const h=(30*(1-t) + P.hue*t)%360, s=60+t*28, bb=26+t*70;
      fill(h,s,bb,92); circle(x,y,sz);
      fill(h,Math.min(100,s+15),bb*0.6,45); circle(x-Math.cos(a)*sz*0.22, y-Math.sin(a)*sz*0.22, sz*0.7);
    }
  }
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
